'use client';

import {
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { useDismiss } from './use-dismiss';
import './anchored-popover.css';

export interface AnchoredPopoverProps {
  /** Text on the trigger button. */
  label: string;
  /** Accessible name of the popover itself. */
  title: string;
  children: ReactNode;
  className?: string;
}

const useIsomorphicLayoutEffect =
  typeof window === 'undefined' ? useEffect : useLayoutEffect;

/**
 * A small panel that opens beside its trigger and grows out of the corner
 * nearest to it. It flips above or shifts sideways to stay inside the
 * nearest ancestor marked `data-popover-boundary` (or the viewport). Escape
 * or an outside press closes it; Escape returns focus to the trigger.
 */
export function AnchoredPopover({
  label,
  title,
  children,
  className = '',
}: AnchoredPopoverProps) {
  const root = useRef<HTMLSpanElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLDivElement>(null);
  const [open, setOpen] = useState(false);
  const [place, setPlace] = useState({
    x: 0,
    y: 0,
    origin: 'top left',
    above: false,
  });
  const id = useId();

  useIsomorphicLayoutEffect(() => {
    if (!open || !root.current || !panel.current || !trigger.current) return;
    const anchor = trigger.current.getBoundingClientRect();
    // offsetWidth/Height ignore the opening scale animation.
    const box = {
      width: panel.current.offsetWidth,
      height: panel.current.offsetHeight,
    };
    const boundaryEl = root.current.closest('[data-popover-boundary]');
    const bounds = boundaryEl
      ? boundaryEl.getBoundingClientRect()
      : new DOMRect(0, 0, window.innerWidth, window.innerHeight);
    const gap = 8;
    const above =
      anchor.bottom + gap + box.height > bounds.bottom &&
      anchor.top - gap - box.height >= bounds.top;
    let left = anchor.left;
    left = Math.min(left, bounds.right - box.width - 4);
    left = Math.max(left, bounds.left + 4);
    const top = above ? anchor.top - gap - box.height : anchor.bottom + gap;
    const own = root.current.getBoundingClientRect();
    const originX = anchor.left + anchor.width / 2 - left;
    setPlace({
      x: left - own.left,
      y: top - own.top,
      origin: `${Math.max(0, Math.min(box.width, originX))}px ${above ? '100%' : '0%'}`,
      above,
    });
    panel.current
      .querySelector<HTMLElement>(
        'button, a[href], input, [tabindex]:not([tabindex="-1"])'
      )
      ?.focus();
  }, [open]);

  const close = (refocus: boolean) => {
    setOpen(false);
    if (refocus) trigger.current?.focus();
  };
  useDismiss(open, [root], (reason) => close(reason === 'escape'));

  return (
    <span ref={root} className={`mg-pop ${className}`}>
      <button
        ref={trigger}
        type='button'
        className='mg-pop__trigger'
        aria-expanded={open}
        aria-controls={id}
        onClick={() => (open ? close(false) : setOpen(true))}
      >
        {label}
      </button>
      {open ? (
        <div
          ref={panel}
          id={id}
          role='dialog'
          aria-label={title}
          className='mg-pop__panel'
          data-above={place.above}
          style={
            {
              transform: `translate(${place.x}px, ${place.y}px)`,
              '--mg-origin': place.origin,
            } as CSSProperties
          }
        >
          {children}
          <button
            type='button'
            className='mg-pop__close'
            onClick={() => close(true)}
          >
            Done
          </button>
        </div>
      ) : null}
    </span>
  );
}

.mg-pop {
  position: relative;
  display: inline-block;
}

.mg-pop__trigger {
  min-height: 44px;
  padding: 0 14px;
  border: 1px solid var(--mg-line-strong, #474747);
  border-radius: 10px;
  background: #121212;
  color: var(--mg-text, #ffffff);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.mg-pop__trigger[aria-expanded='true'] {
  border-color: var(--mg-accent-text, #dce9f7);
  background: #1e2329;
}

.mg-pop__trigger:focus-visible,
.mg-pop__close:focus-visible {
  outline: 3px solid var(--mg-accent-text, #dce9f7);
  outline-offset: 2px;
}

.mg-pop__panel {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 20;
  display: grid;
  gap: 10px;
  width: 210px;
  padding: 14px;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 12px;
  background: #121212;
  box-shadow: 0 18px 36px -16px rgba(0, 0, 0, 0.5);
  color: #b8b8b8;
  font-size: 13px;
}

/* The scale grows out of the point nearest the trigger. */
.mg-pop__panel {
  animation: mg-pop-in 200ms cubic-bezier(0.2, 0.9, 0.3, 1.2);
  transform-origin: var(--mg-origin);
}

.mg-pop__close {
  justify-self: end;
  min-height: 36px;
  padding: 0 12px;
  border: 0;
  border-radius: 8px;
  background: var(--mg-accent, #eaf2fb);
  color: #080808;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

@keyframes mg-pop-in {
  from {
    opacity: 0;
    scale: 0.85;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-pop__panel {
    animation: none;
  }
}

'use client';

import { useEffect, useRef, type RefObject } from 'react';

export type DismissReason = 'escape' | 'outside';

/**
 * While `active`, calls `onDismiss` when Escape is pressed or when a pointer
 * goes down outside every element in `refs`. Decide where focus goes in
 * `onDismiss`: back to the trigger after Escape, left alone after an
 * outside press.
 */
export function useDismiss(
  active: boolean,
  refs: RefObject<HTMLElement | null>[],
  onDismiss: (reason: DismissReason) => void
) {
  const callback = useRef(onDismiss);
  callback.current = onDismiss;
  const inside = useRef(refs);
  inside.current = refs;

  useEffect(() => {
    if (!active) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      event.preventDefault();
      callback.current('escape');
    };
    const onPointerDown = (event: PointerEvent) => {
      const target = event.target as Node;
      if (inside.current.some((ref) => ref.current?.contains(target))) return;
      callback.current('outside');
    };
    document.addEventListener('keydown', onKeyDown);
    document.addEventListener('pointerdown', onPointerDown);
    return () => {
      document.removeEventListener('keydown', onKeyDown);
      document.removeEventListener('pointerdown', onPointerDown);
    };
  }, [active]);
}
